//                  {
//                    sBSP1.LocalPointSolve(sIvl1,m_eSolverOperation,sEnd2,&m_d3dTolerance,NULL,m_cpOptVectors,
//                        sIvl1.Evaluate(0.5),bFoundAnswer,sPointSolution);
