//                // when a solution was found - save it
//                if (bFoundAnswer)
//                  {
//                    sSolution.m_vStart.m_dSolutionValue = sPointSolution.m_vStart.m_dSolutionValue;
//                    if (m_eSolverOperation == SM_SO_3D_SIGNED_DIRECTED_MINIMIZE)
//                      {
