//          sC2_t_Unit_t = sPVV2[2].UnitizedDerivative( sPVV2[3] );
//      }
//
//          double dTerm11 = -sPVV1[1].Dot( sC1_t_Unit   );
//          double dTerm12 =  sGapVec .Dot( sC1_t_Unit_t );
//          double dTerm21 =  sPVV2[1].Dot( sC2_t_Unit   );
