//    } // end No Split Point Found check
//
//  // when a splitPoint was found
//  if (bSplit)
//    {
//      // If the solution value at the split point is very much better
//      // than those at the ends of the coincidence interval,
//      // create a single crossing intersection.  [B296]
//      if ( dSplitDev < smos_Min( daDev[0], daDev[lNumT-1]) / 1000.0 )
//        {
//          // Add one single Intersection at split point.
//          aSolutions[0].m_lNumVariables           = 2;
//          aSolutions[0].m_lNumObjects             = 2;
//          aSolutions[0].m_vStart[0]               = dSplit1;
//          aSolutions[0].m_vStart[1]               = dSplit2;
//          aSolutions[0].m_vStart.m_dSolutionValue = dSplitDev;
//          aSolutions[0].m_eSolutionType           = SM_ST_SINGLE_VALUE;
//          aSolutions[0].m_apObjects[0]            = (SmObject *)this ;
//          aSolutions[0].m_apObjects[1]            = (SmObject *)&crOtherCurve ;
//          rlNumFound = 1;
