/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmCurve::Dump
  (void)
 const
{
  Dump(FALSE);

} // end SmCurve::Dump

/*******************************************************************//**
PURPOSE:

NOTES:
***********************************************************************/
void SmCurve::Dump
  (SmBoolean )     // in : bAbbrev
 const
{
  TCHAR sBuff[SM_TBLOCK_SIZE], sBuffForFile[SM_TBLOCK_SIZE];
  smos_WriteBuffer(_T("\nBegin SmCurve::Dump()")) ;

  // get CurveCache state
  SmCurveCache *pCurveCache = (SmCurveCache *)SmCacheMgr::GetObjectCache(SM_OC_CURVE, this) ;
  ULONG lMemoryAllocated = 0 ;
//  ULONG lMemoryUsed = pCurveCache ? pCurveCache->GetMemoryUsed(lMemoryAllocated) : 0 ;
  if( pCurveCache )
      pCurveCache->GetMemoryUsed(lMemoryAllocated);


  // get derived curve type string
  TCHAR sDerivedName[SM_TBLOCK_SIZE] ;
  switch(GetType())
    { case SmCurve_TYPE               : smos_sprintf(sDerivedName,_T("%s"), _T(" ")) ; break ;
      case SmBSplineCurve_TYPE        : smos_sprintf(sDerivedName,_T("%s"), _T("[SmBSplineCurve_TYPE]")) ;   break ;
      case SmCrvOnSurf_TYPE           : smos_sprintf(sDerivedName,_T("%s"), _T("[SmCrvOnSurf_TYPE]")) ;      break ;
      case SmTangentField_TYPE        : smos_sprintf(sDerivedName,_T("%s"), _T("[SmTangentField_TYPE]")) ;   break ;
      case SmIsoCurve_TYPE            : smos_sprintf(sDerivedName,_T("%s"), _T("[SmIsoCurve_TYPE]")) ;       break ;
      case SmEllipse_TYPE             : smos_sprintf(sDerivedName,_T("%s"), _T("[SmEllipse_TYPE]")) ;        break ;
      case SmCircle_TYPE              : smos_sprintf(sDerivedName,_T("%s"), _T("[SmCircle_TYPE]")) ;         break ;
      case SmHyperbola_TYPE           : smos_sprintf(sDerivedName,_T("%s"), _T("[SmHyperbola_TYPE]")) ;      break ;
      case SmLine_TYPE                : smos_sprintf(sDerivedName,_T("%s"), _T("[SmLine_TYPE]")) ;           break ;
      case SmParabola_TYPE            : smos_sprintf(sDerivedName,_T("%s"), _T("[SmParabola_TYPE]")) ;       break ;
      case SmCompositeCurve_TYPE      : smos_sprintf(sDerivedName,_T("%s"), _T("[SmCompositeCurve_TYPE]")) ; break ;
      case SmConic_TYPE               : smos_sprintf(sDerivedName,_T("%s"), _T("[SmConic_TYPE]")) ;          break ;
      case SmHermiteCurve_TYPE        : smos_sprintf(sDerivedName,_T("%s"), _T("[SmHermiteCurve_TYPE]")) ;   break ;
      case SmOffsetCurve_TYPE         : smos_sprintf(sDerivedName,_T("%s"), _T("[SmOffsetCurve_TYPE]")) ;    break ;
      case SmProjectedCurve_TYPE      : smos_sprintf(sDerivedName,_T("%s"), _T("[SmProjectedCurve_TYPE]")) ; break ;
      case SmCrvInVolume_TYPE         : smos_sprintf(sDerivedName,_T("%s"), _T("[SmCrvInVolume_TYPE]")) ;     break ;
      default : smos_sprintf(sDerivedName,_T("%s"), _T("[UnKnown Derived Type]")) ; break ;
    }

  smos_sprintf(sBuff,
             _T("\nSmCurve%.512s 0x%p, [pCurveCache = 0x%p (%lu bytes)]"),
             sDerivedName,
             this,
             pCurveCache,
             lMemoryAllocated);
  smos_sprintf(sBuffForFile,
             _T("\nSmCurve%.256s = %.256s, [pCurveCache = %.256s (%lu bytes)]"),
             sDerivedName,
             _T("NotNULL"),
             pCurveCache ? _T("NotNULL") : _T("NULL"),
             lMemoryAllocated);
  smos_WriteBuffer(sBuff, sBuffForFile);

  smos_WriteBuffer(_T("\nEnd SmCurve::Dump()\n")) ;

} // end SmCurve::Dump

